		if err != nil {
			return err
		}
		var latest *store.Verdict
		for index := len(verdicts) - 1; index >= 0; index-- {
			verdict := verdicts[index]
			if verdict.Repository == project.Name && verdict.Mode == "gate" && verdict.Head == head {
				latest = &verdict
				break
			}
