248: // refreshPRValidationBlock rewrites the Validation block of an open PR/MR when
249: // the evidence digest changed since the last write. It is best effort: a body
250: // without Posse's token span is left alone.
251: func (s *Service) refreshPRValidationBlock(ctx context.Context, db *store.DB, project store.Project, task store.Task, forge repositoryForge, prURL, member string) error {
252: 	if task.Type != "change" || prURL == "" {
253: 		return nil
254: 	}
255: 	marker, err := db.GetPRBodyMarker(ctx, task.ID, member)
256: 	if err != nil {
257: 		if store.IsNotFound(err) {
258: 			return nil
259: 		}
260: 		return err
261: 	}
262: 	if marker.PRURL != prURL {
263: 		return nil
264: 	}
265: 	summary, err := validationSummaryFor(ctx, db, task, member)
266: 	if err != nil {
267: 		return err
268: 	}
269: 	digest := summary.digest()
270: 	var written string
271: 	if err := db.QueryRowContext(ctx, `SELECT validation_digest FROM pr_body_markers WHERE task_id=? AND repo=?`, task.ID, member).Scan(&written); err != nil {
272: 		return err
273: 	}
274: 	if written == digest {
275: 		return nil
276: 	}
277: 	existing, err := readForgeBody(ctx, forge, prURL)
278: 	if err != nil {
279: 		return err
280: 	}
281: 	next, ok := replaceValidationBlock(existing, marker.Token, summary.markdown())
282: 	if ok && next != existing {
283: 		if err := writeForgeBody(ctx, forge, prURL, next); err != nil {
284: 			return err
285: 		}
286: 	}
287: 	_, err = db.ExecContext(ctx, `UPDATE pr_body_markers SET validation_digest=? WHERE task_id=? AND repo=? AND marker_token=?`, digest, task.ID, member, marker.Token)
288: 	return err
